def count_words(text):
    return len(text.split())


def wrap(text, width):
    lines = []
    cur = ""
    for w in text.split():
        extra = len(w) + (1 if cur else 0)
        if len(cur) + extra > width:
            lines.append(cur)
            cur = w
        else:
            cur = f"{cur} {w}" if cur else w
    if cur:
        lines.append(cur)
    return lines


# Fix for when a single word is longer than the width:
# When cur is empty (no line built yet), we should just use the word directly
# without trying to add anything before it.

def wrap_fixed(text, width):
    words = text.split()
    if not words:
        return []

    lines = []
    cur = ""
    for w in words:
        if len(cur) + 1 + len(w) > width and cur != "":
            # Word doesn't fit on the current line, start new line with this word
            lines.append(cur)
            cur = w
        elif len(cur) + len(w) > width and not cur:
            # Single word is longer than width, put it on its own line
            lines.append(w)
            cur = ""
        else:
            # Word fits, add to current line
            if cur:
                cur = f"{cur} {w}"
            else:
                cur = w

    if cur:
        lines.append(cur)
    return lines


